using System;
using System.Threading;

// ========== 1. 推荐写法：Lazy<T> 线程安全惰性单例 ==========
public sealed class AppConfig
{
    private static readonly Lazy<AppConfig> _instance =
        new(() => new AppConfig());

    public static AppConfig Instance => _instance.Value;

    public string ApiBase { get; }
    public int TimeoutMs { get; }

    private AppConfig()
    {
        // 模拟从文件 / 环境变量加载，只执行一次
        ApiBase = Environment.GetEnvironmentVariable("API_BASE")
                  ?? "https://api.example.com";
        TimeoutMs = 5000;
        Console.WriteLine("[AppConfig] 初始化完成");
    }
}

// ========== 2. 日志器：单例实现接口，便于测试替换 ==========
public interface ILogger
{
    void Info(string msg);
}

public sealed class FileLogger : ILogger
{
    private static readonly Lazy<FileLogger> _inst = new(() => new FileLogger());
    public static FileLogger Instance => _inst.Value;
    private readonly object _lock = new();

    private FileLogger() { }

    public void Info(string msg)
    {
        lock (_lock)
            Console.WriteLine($"[{DateTime.Now:HH:mm:ss}] {msg}");
    }
}

// ========== 3. 使用演示 ==========
var a = AppConfig.Instance;
var b = AppConfig.Instance;
Console.WriteLine(ReferenceEquals(a, b));   // True，同一实例
Console.WriteLine($"{a.ApiBase} timeout={a.TimeoutMs}");

FileLogger.Instance.Info("服务启动");
FileLogger.Instance.Info("读取配置完成");

