using System;
using System.Collections.Concurrent;

// ========== 1. 双重检查锁（了解即可，优先用 Lazy<T>） ==========
public sealed class DclSingleton
{
    private static DclSingleton _instance;
    private static readonly object _lock = new();
    public static DclSingleton Instance
    {
        get
        {
            if (_instance is null)
            {
                lock (_lock)
                {
                    _instance ??= new DclSingleton();
                }
            }
            return _instance;
        }
    }
    private DclSingleton() { }
}

// ========== 2. 静态构造：CLR 保证类型初始化线程安全 ==========
public sealed class StaticCtorSingleton
{
    public static StaticCtorSingleton Instance { get; } = new();
    private StaticCtorSingleton() { }
}

// ========== 3. 按 key 的多例（小对象池，不是严格单例） ==========
public sealed class DbConnectionPool
{
    private static readonly ConcurrentDictionary<string, DbConnectionPool> _pool = new();
    public string Name { get; }
    private DbConnectionPool(string name) => Name = name;

    public static DbConnectionPool Get(string name) =>
        _pool.GetOrAdd(name, n => new DbConnectionPool(n));
}

