using System;

// ========== 产品层次 ==========
public abstract class Transport
{
    public abstract string Name { get; }
    public abstract void Deliver(string cargo);
}

public class Truck : Transport
{
    public override string Name => "卡车";
    public override void Deliver(string cargo) =>
        Console.WriteLine($"[公路] {Name} 运送 {cargo}");
}

public class Ship : Transport
{
    public override string Name => "货轮";
    public override void Deliver(string cargo) =>
        Console.WriteLine($"[海运] {Name} 运送 {cargo}");
}

public class Plane : Transport
{
    public override string Name => "货机";
    public override void Deliver(string cargo) =>
        Console.WriteLine($"[空运] {Name} 运送 {cargo}（加急）");
}

// ========== 创建者：骨架固定，产品由子类决定 ==========
public abstract class Logistics
{
    // 工厂方法：子类重写，决定 new 哪一种 Transport
    protected abstract Transport CreateTransport();

    public void PlanDelivery(string cargo)
    {
        var t = CreateTransport();          // 不写 new Truck()
        Console.WriteLine($"调度 {t.Name}");
        t.Deliver(cargo);
    }
}

public class RoadLogistics : Logistics
{
    protected override Transport CreateTransport() => new Truck();
}
public class SeaLogistics : Logistics
{
    protected override Transport CreateTransport() => new Ship();
}
public class AirLogistics : Logistics
{
    protected override Transport CreateTransport() => new Plane();
}

// ========== 客户端只依赖 Logistics 抽象 ==========
void Run(Logistics logistics, string cargo) => logistics.PlanDelivery(cargo);

Run(new RoadLogistics(), "零件箱");   // 公路
Run(new SeaLogistics(), "集装箱");    // 海运
Run(new AirLogistics(), "疫苗");      // 空运

