using System;

// ========== 抽象产品（产品族：按钮 + 复选框） ==========
public interface IButton { void Paint(); void Click(); }
public interface ICheckbox { void Paint(); void Toggle(); }

// Windows 族
public class WinButton : IButton
{
    public void Paint() => Console.WriteLine("绘制 Win 扁平按钮");
    public void Click() => Console.WriteLine("Win 按钮被点击");
}
public class WinCheckbox : ICheckbox
{
    public void Paint() => Console.WriteLine("绘制 Win 方框复选框");
    public void Toggle() => Console.WriteLine("Win 复选框切换");
}

// Mac 族
public class MacButton : IButton
{
    public void Paint() => Console.WriteLine("绘制 Mac 圆角按钮");
    public void Click() => Console.WriteLine("Mac 按钮被点击");
}
public class MacCheckbox : ICheckbox
{
    public void Paint() => Console.WriteLine("绘制 Mac 圆形复选框");
    public void Toggle() => Console.WriteLine("Mac 复选框切换");
}

// ========== 抽象工厂：一次创建整族产品 ==========
public interface IGuiFactory
{
    IButton CreateButton();
    ICheckbox CreateCheckbox();
}

public class WinFactory : IGuiFactory
{
    public IButton CreateButton() => new WinButton();
    public ICheckbox CreateCheckbox() => new WinCheckbox();
}
public class MacFactory : IGuiFactory
{
    public IButton CreateButton() => new MacButton();
    public ICheckbox CreateCheckbox() => new MacCheckbox();
}

// 客户端：只依赖抽象，风格由工厂注入
public class Dialog
{
    private readonly IButton _ok;
    private readonly ICheckbox _agree;
    public Dialog(IGuiFactory factory)
    {
        _ok = factory.CreateButton();
        _agree = factory.CreateCheckbox();
    }
    public void Render()
    {
        _ok.Paint();
        _agree.Paint();   // 同一族，风格一致
    }
    public void Submit() { _agree.Toggle(); _ok.Click(); }
}

IGuiFactory factory = OperatingSystem.IsWindows()
    ? new WinFactory() : new MacFactory();
var dlg = new Dialog(factory);
dlg.Render();
dlg.Submit();

