using System;

public interface IAppDbConnection
{
    void Open();
    IAppDbCommand CreateCommand(string sql);
}
public interface IAppDbCommand
{
    int Execute();
}
public interface IAppDbTransaction
{
    void Commit();
    void Rollback();
}
public interface IAppDbFactory
{
    IAppDbConnection CreateConnection();
    IAppDbTransaction Begin();
}

public class SqlServerConnection : IAppDbConnection
{
    public void Open() => Console.WriteLine("打开 SQL Server");
    public IAppDbCommand CreateCommand(string sql) => new SqlServerCommand(sql);
}
public class SqlServerCommand : IAppDbCommand
{
    private readonly string _sql;
    public SqlServerCommand(string sql) => _sql = sql;
    public int Execute() { Console.WriteLine($"T-SQL: {_sql}"); return 1; }
}
public class SqlServerTx : IAppDbTransaction
{
    public void Commit() => Console.WriteLine("SQL Server COMMIT");
    public void Rollback() => Console.WriteLine("SQL Server ROLLBACK");
}
public class SqlServerFactory : IAppDbFactory
{
    public IAppDbConnection CreateConnection() => new SqlServerConnection();
    public IAppDbTransaction Begin() => new SqlServerTx();
}

public class PostgresConnection : IAppDbConnection
{
    public void Open() => Console.WriteLine("打开 PostgreSQL");
    public IAppDbCommand CreateCommand(string sql) => new PostgresCommand(sql);
}
public class PostgresCommand : IAppDbCommand
{
    private readonly string _sql;
    public PostgresCommand(string sql) => _sql = sql;
    public int Execute() { Console.WriteLine($"PG: {_sql}"); return 1; }
}
public class PostgresTx : IAppDbTransaction
{
    public void Commit() => Console.WriteLine("PG COMMIT");
    public void Rollback() => Console.WriteLine("PG ROLLBACK");
}
public class PostgresFactory : IAppDbFactory
{
    public IAppDbConnection CreateConnection() => new PostgresConnection();
    public IAppDbTransaction Begin() => new PostgresTx();
}

void Migrate(IAppDbFactory f)
{
    var conn = f.CreateConnection();
    conn.Open();
    var tx = f.Begin();
    conn.CreateCommand("UPDATE users SET active=1").Execute();
    tx.Commit();          // 连接、命令、事务来自同一产品族
}

Migrate(new SqlServerFactory());
Migrate(new PostgresFactory());

