using System;
using System.Collections.Generic;

// 不可变产品：构造后不能改
public sealed class Pizza
{
    public string Dough { get; }
    public string Sauce { get; }
    public string Size { get; }
    public IReadOnlyList<string> Toppings { get; }
    public bool ExtraCheese { get; }

    internal Pizza(string dough, string sauce, string size,
                   List<string> toppings, bool extraCheese)
    {
        Dough = dough; Sauce = sauce; Size = size;
        Toppings = toppings.AsReadOnly();
        ExtraCheese = extraCheese;
    }

    public override string ToString() =>
        $"{Size} {Dough}饼 / {Sauce}酱 / " +
        $"配料[{string.Join(",", Toppings)}]" +
        (ExtraCheese ? " + Extra芝士" : "");
}

public class PizzaBuilder
{
    private string _dough = "薄底", _sauce = "番茄", _size = "12寸";
    private readonly List<string> _toppings = new();
    private bool _extra;

    public PizzaBuilder Dough(string d) { _dough = d; return this; }
    public PizzaBuilder Sauce(string s) { _sauce = s; return this; }
    public PizzaBuilder Size(string s) { _size = s; return this; }
    public PizzaBuilder AddTopping(string t) { _toppings.Add(t); return this; }
    public PizzaBuilder ExtraCheese(bool v = true) { _extra = v; return this; }

    public Pizza Build()
    {
        if (_toppings.Count == 0)
            throw new InvalidOperationException("至少一种配料");
        return new Pizza(_dough, _sauce, _size, new List<string>(_toppings), _extra);
    }
}

