    .Size("9寸").Dough("厚底").Sauce("番茄")
    .AddTopping("火腿").AddTopping("菠萝")
    .ExtraCheese()
    .Build();
Console.WriteLine(hawaiian);

var veggie = new PizzaBuilder()
    .AddTopping("蘑菇").AddTopping("青椒").Build();
Console.WriteLine(veggie);

