public sealed class HttpRequest
{
    public string Method { get; init; }
    public string Url { get; init; }
    public Dictionary<string, string> Headers { get; init; }
    public string Body { get; init; }
    public int TimeoutMs { get; init; }
    public override string ToString() =>
        $"{Method} {Url} timeout={TimeoutMs} headers={Headers.Count} bodyLen={Body?.Length ?? 0}";
}

public class HttpRequestBuilder
{
    private string _method = "GET", _url, _body = "";
    private int _timeout = 10_000;
    private readonly Dictionary<string, string> _headers = new();

    public HttpRequestBuilder Get(string url) { _method = "GET"; _url = url; return this; }
    public HttpRequestBuilder Post(string url) { _method = "POST"; _url = url; return this; }
    public HttpRequestBuilder Header(string k, string v) { _headers[k] = v; return this; }
    public HttpRequestBuilder Json(string json)
    {
        _body = json;
        _headers["Content-Type"] = "application/json";
        return this;
    }
    public HttpRequestBuilder Timeout(int ms) { _timeout = ms; return this; }
    public HttpRequest Build()
    {
        if (string.IsNullOrEmpty(_url)) throw new InvalidOperationException("缺少 Url");
        return new HttpRequest {
            Method = _method, Url = _url, Body = _body,
            TimeoutMs = _timeout, Headers = new(_headers)
        };
    }
}

