using System;
using System.Collections.Generic;

public interface IPrototype<out T>
{
    T Clone();
}

public class WorkExp
{
    public string Company { get; set; }
    public int Years { get; set; }
    public WorkExp Clone() => new() { Company = Company, Years = Years };
}

public class Resume : IPrototype<Resume>
{
    public string Name { get; set; }
    public List<string> Skills { get; set; } = new();
    public WorkExp Experience { get; set; }

    public Resume Clone() => new Resume
    {
        Name = Name,
        Skills = new List<string>(Skills),     // 深拷贝列表
        Experience = Experience?.Clone()       // 深拷贝嵌套对象
    };

    public Resume ShallowClone() => (Resume)MemberwiseClone();
}

var proto = new Resume
{
    Name = "张三",
    Skills = new List<string> { "C#", "SQL" },
    Experience = new WorkExp { Company = "Acme", Years = 3 }
};

// 深拷贝：互不影响
var deep = proto.Clone();
deep.Name = "李四";
deep.Skills.Add("Redis");
deep.Experience.Company = "Beta";
Console.WriteLine($"{proto.Name} {string.Join(",", proto.Skills)} {proto.Experience.Company}");
Console.WriteLine($"{deep.Name} {string.Join(",", deep.Skills)} {deep.Experience.Company}");

// 浅拷贝：引用成员共享
var shallow = proto.ShallowClone();
shallow.Skills.Add("误伤原型");
Console.WriteLine("原型技能: " + string.Join(",", proto.Skills));

