public interface IPrototype<out T> { T Clone(); }

// 原型注册表：预置几种模板，按名克隆
public class Document : IPrototype<Document>
{
    public string Title { get; set; }
    public string Theme { get; set; }
    public List<string> Pages { get; set; } = new();
    public Document Clone() => new Document
    {
        Title = Title, Theme = Theme,
        Pages = new List<string>(Pages)
    };
}

public class PrototypeRegistry
{
    private readonly Dictionary<string, Document> _map = new();
    public void Register(string key, Document proto) => _map[key] = proto;
    public Document Create(string key) =>
        _map.TryGetValue(key, out var p)
            ? p.Clone()
            : throw new KeyNotFoundException(key);
}

