using System;

// 客户端只认识这个接口
public interface IPaymentGateway
{
    bool Charge(decimal amountCny, string orderId);
}

// 第三方 SDK：美元、方法名不同，无法直接用
public class StripeSdk
{
    public string CreateCharge(long amountCents, string currency, string idempotencyKey)
    {
        Console.WriteLine($"Stripe {amountCents} {currency} key={idempotencyKey}");
        return "ch_123";
    }
}

// 遗留支付宝：签名、分单位
public class LegacyAlipay
{
    public int Pay(int fen, string tradeNo)
    {
        Console.WriteLine($"Alipay {fen} 分, trade={tradeNo}");
        return 0; // 0 表示成功
    }
}

public class StripeAdapter : IPaymentGateway
{
    private readonly StripeSdk _sdk = new();
    public bool Charge(decimal amountCny, string orderId)
    {
        var usdCents = (long)(amountCny / 7.2m * 100);
        var id = _sdk.CreateCharge(usdCents, "usd", orderId);
        return id.StartsWith("ch_");
    }
}

public class AlipayAdapter : IPaymentGateway
{
    private readonly LegacyAlipay _pay = new();
    public bool Charge(decimal amountCny, string orderId) =>
        _pay.Pay((int)(amountCny * 100), orderId) == 0;
}

void Checkout(IPaymentGateway gw, decimal price, string orderId)
{
    Console.WriteLine(gw.Charge(price, orderId) ? "支付成功" : "失败");
}

Checkout(new StripeAdapter(), 72m, "ORD-001");
Checkout(new AlipayAdapter(), 72m, "ORD-002");

