using System;

// 实现者层次：怎么画
public interface IRenderer
{
    void RenderCircle(double x, double y, double r);
    void RenderRect(double x, double y, double w, double h);
}

public class VectorRenderer : IRenderer
{
    public void RenderCircle(double x, double y, double r) =>
        Console.WriteLine($"SVG circle cx={x} cy={y} r={r}");
    public void RenderRect(double x, double y, double w, double h) =>
        Console.WriteLine($"SVG rect x={x} y={y} {w}x{h}");
}

public class RasterRenderer : IRenderer
{
    public void RenderCircle(double x, double y, double r) =>
        Console.WriteLine($"像素圆 ({x},{y}) r={r}");
    public void RenderRect(double x, double y, double w, double h) =>
        Console.WriteLine($"像素矩形 ({x},{y}) {w}x{h}");
}

// 抽象层次：画什么，持有渲染器（桥）
public abstract class Shape
{
    protected readonly IRenderer Renderer;
    protected Shape(IRenderer renderer) => Renderer = renderer;
    public abstract void Draw();
    public abstract void Resize(double factor);
}

public class Circle : Shape
{
    private double _x, _y, _r;
    public Circle(IRenderer r, double x, double y, double radius) : base(r)
    { _x = x; _y = y; _r = radius; }
    public override void Draw() => Renderer.RenderCircle(_x, _y, _r);
    public override void Resize(double f) => _r *= f;
}

public class Rectangle : Shape
{
    private double _x, _y, _w, _h;
    public Rectangle(IRenderer r, double x, double y, double w, double h) : base(r)
    { _x = x; _y = y; _w = w; _h = h; }
    public override void Draw() => Renderer.RenderRect(_x, _y, _w, _h);
    public override void Resize(double f) { _w *= f; _h *= f; }
}

// 2 种形状 × 2 种渲染 = 4 种组合，只需 4 个类而不是 4 个继承叶子
Shape[] shapes =
{
    new Circle(new VectorRenderer(), 10, 10, 5),
    new Circle(new RasterRenderer(), 0, 0, 3),
    new Rectangle(new VectorRenderer(), 1, 1, 8, 4)
};
foreach (var s in shapes) { s.Resize(2); s.Draw(); }

