public abstract class FileSystemNode
{
    public string Name { get; }
    protected FileSystemNode(string name) => Name = name;
    public abstract long Size();
    public abstract void Print(int depth = 0);
    protected string Indent(int d) => new string(' ', d * 2);
}

public class FileNode : FileSystemNode
{
    private readonly long _bytes;
    public FileNode(string name, long bytes) : base(name) => _bytes = bytes;
    public override long Size() => _bytes;
    public override void Print(int depth = 0) =>
        Console.WriteLine($"{Indent(depth)}- {Name} ({_bytes}B)");
}

public class FolderNode : FileSystemNode
{
    private readonly List<FileSystemNode> _children = new();
    public FolderNode(string name) : base(name) { }
    public FolderNode Add(FileSystemNode child)
    {
        _children.Add(child);
        return this;
    }
    public override long Size() => _children.Sum(c => c.Size());
    public override void Print(int depth = 0)
    {
        Console.WriteLine($"{Indent(depth)}+ {Name}/  ({Size()}B)");
        foreach (var c in _children) c.Print(depth + 1);
    }
}

