public class Shipping
{
    public string CreateWaybill(string addr)
    {
        var no = "SF" + DateTime.Now.Ticks;
        Console.WriteLine($"运单 {no} -> {addr}");
        return no;
    }
}
public class Notify
{
    public void Mail(string user, string body) => Console.WriteLine($"通知 {user}: {body}");
}

// ----- 外观：一键下单 -----
public class OrderFacade
{
    private readonly Inventory _inv = new();
    private readonly Payment _pay = new();
    private readonly Shipping _ship = new();
    private readonly Notify _n = new();

    public string Place(string user, string sku, int qty, decimal price, string addr)
    {
        if (!_inv.Reserve(sku, qty)) throw new InvalidOperationException("缺货");
        var amount = price * qty;
        if (!_pay.Charge(user, amount))
        {
            _inv.Release(sku, qty);
            throw new InvalidOperationException("支付失败");
        }
        var wb = _ship.CreateWaybill(addr);
        _n.Mail(user, $"下单成功，运单 {wb}");
        return wb;
    }
}

