using System;
using System.Collections.Generic;

// 内部状态：字体/字号/颜色，可被成千上万字符共享
public sealed class GlyphStyle
{
    public string Font { get; }
    public int Size { get; }
    public string Color { get; }
    public GlyphStyle(string font, int size, string color)
    { Font = font; Size = size; Color = color; }
    public override string ToString() => $"{Font} {Size}px {Color}";
}

public class StyleFactory
{
    private readonly Dictionary<string, GlyphStyle> _pool = new();
    public int PoolSize => _pool.Count;

    public GlyphStyle Get(string font, int size, string color)
    {
        var key = $"{font}|{size}|{color}";
        if (!_pool.TryGetValue(key, out var style))
            _pool[key] = style = new GlyphStyle(font, size, color);
        return style;
    }
}

// 外部状态：字符本身、坐标，每个字符不同，不放进享元
public readonly struct Glyph
{
    public char Char { get; }
    public int X { get; }
    public int Y { get; }
    public GlyphStyle Style { get; }
    public Glyph(char c, int x, int y, GlyphStyle s)
    { Char = c; X = x; Y = y; Style = s; }
    public void Draw() => Console.WriteLine($"'{Char}' @({X},{Y}) {Style}");
}

var factory = new StyleFactory();
var body = factory.Get("宋体", 14, "黑");
var title = factory.Get("黑体", 22, "蓝");

