using System;

public class SupportTicket
{
    public string Title { get; init; }
    public int Severity { get; init; }   // 1 低 ~ 3 紧急
    public bool Handled { get; set; }
}

public abstract class SupportHandler
{
    private SupportHandler _next;
    public SupportHandler SetNext(SupportHandler next)
    {
        _next = next;
        return next;              // 便于链式拼接
    }
    public void Handle(SupportTicket t)
    {
        if (CanHandle(t))
        {
            Process(t);
            t.Handled = true;
            return;
        }
        Console.WriteLine($"{GetType().Name} 无法处理，转交下级");
        _next?.Handle(t);
        if (!t.Handled && _next is null)
            Console.WriteLine("整条链都无法处理: " + t.Title);
    }
    protected abstract bool CanHandle(SupportTicket t);
    protected abstract void Process(SupportTicket t);
}

public class L1Helpdesk : SupportHandler
{
    protected override bool CanHandle(SupportTicket t) => t.Severity <= 1;
    protected override void Process(SupportTicket t) =>
        Console.WriteLine($"L1 重置密码/答疑: {t.Title}");
}
public class L2Engineer : SupportHandler
{
    protected override bool CanHandle(SupportTicket t) => t.Severity == 2;
    protected override void Process(SupportTicket t) =>
        Console.WriteLine($"L2 排查缺陷: {t.Title}");
}
public class L3Architect : SupportHandler
{
    protected override bool CanHandle(SupportTicket t) => t.Severity >= 3;
    protected override void Process(SupportTicket t) =>
        Console.WriteLine($"L3 紧急响应: {t.Title}");
}

var chain = new L1Helpdesk();
chain.SetNext(new L2Engineer()).SetNext(new L3Architect());

chain.Handle(new SupportTicket { Title = "无法登录", Severity = 1 });
chain.Handle(new SupportTicket { Title = "支付失败", Severity = 2 });
chain.Handle(new SupportTicket { Title = "全站宕机", Severity = 3 });

