using System;
using System.Collections.Generic;

public interface ICommand
{
    void Execute();
    void Undo();
}

public class Light
{
    public bool On { get; private set; }
    public void TurnOn() { On = true; Console.WriteLine("灯开"); }
    public void TurnOff() { On = false; Console.WriteLine("灯关"); }
}
public class Stereo
{
    public int Volume { get; private set; } = 5;
    public void SetVolume(int v) { Volume = v; Console.WriteLine("音量 " + v); }
}

public class LightOnCommand : ICommand
{
    private readonly Light _light;
    public LightOnCommand(Light light) => _light = light;
    public void Execute() => _light.TurnOn();
    public void Undo() => _light.TurnOff();
}
public class VolumeCommand : ICommand
{
    private readonly Stereo _stereo;
    private readonly int _target;
    private int _prev;
    public VolumeCommand(Stereo s, int target) { _stereo = s; _target = target; }
    public void Execute() { _prev = _stereo.Volume; _stereo.SetVolume(_target); }
    public void Undo() => _stereo.SetVolume(_prev);
}

// 宏命令：一次执行多条
public class MacroCommand : ICommand
{
    private readonly ICommand[] _cmds;
    public MacroCommand(params ICommand[] cmds) => _cmds = cmds;
    public void Execute() { foreach (var c in _cmds) c.Execute(); }
    public void Undo() { for (int i = _cmds.Length - 1; i >= 0; i--) _cmds[i].Undo(); }
}

public class Remote
{
    private readonly Stack<ICommand> _undo = new();
    private readonly Stack<ICommand> _redo = new();
    public void Press(ICommand cmd)
    {
        cmd.Execute();
        _undo.Push(cmd);
        _redo.Clear();
    }
    public void Undo() { if (_undo.Count == 0) return; var c = _undo.Pop(); c.Undo(); _redo.Push(c); }
    public void Redo() { if (_redo.Count == 0) return; var c = _redo.Pop(); c.Execute(); _undo.Push(c); }
}

var light = new Light();
var stereo = new Stereo();
var remote = new Remote();
var movieNight = new MacroCommand(new LightOnCommand(light), new VolumeCommand(stereo, 12));
remote.Press(movieNight);
remote.Undo();    // 音量还原，再关灯
remote.Redo();

