public class DeleteCommand : ICommand
{
    private readonly Document _doc;
    private readonly int _index, _len;
    private string _deleted;
    public DeleteCommand(Document d, int i, int len) { _doc = d; _index = i; _len = len; }
    public void Execute() => _deleted = _doc.Delete(_index, _len);
    public void Undo() => _doc.Insert(_index, _deleted);
}

