        ctx.TryGetValue(_key, out var v) && v is true;
}
public class GreaterThan : IBoolExpr
{
    private readonly string _key;
    private readonly decimal _n;
    public GreaterThan(string key, decimal n) { _key = key; _n = n; }
    public bool Eval(Dictionary<string, object> ctx) =>
        Convert.ToDecimal(ctx[_key]) > _n;
}
public class And : IBoolExpr
{
    private readonly IBoolExpr _l, _r;
    public And(IBoolExpr l, IBoolExpr r) { _l = l; _r = r; }
    public bool Eval(Dictionary<string, object> ctx) => _l.Eval(ctx) && _r.Eval(ctx);
}
public class Or : IBoolExpr
{
    private readonly IBoolExpr _l, _r;
    public Or(IBoolExpr l, IBoolExpr r) { _l = l; _r = r; }
    public bool Eval(Dictionary<string, object> ctx) => _l.Eval(ctx) || _r.Eval(ctx);
}

