using System;
using System.Collections.Generic;
using System.Linq;

public class Node
{
    public int Value;
    public Node Left, Right;
    public Node(int v) => Value = v;
}

public class BinaryTree
{
    public Node Root { get; set; }

    public IEnumerable<int> InOrder()
    {
        IEnumerable<int> Walk(Node n)
        {
            if (n is null) yield break;
            foreach (var x in Walk(n.Left)) yield return x;
            yield return n.Value;
            foreach (var x in Walk(n.Right)) yield return x;
        }
        return Walk(Root);
    }

    public IEnumerable<int> PreOrder()
    {
        IEnumerable<int> Walk(Node n)
        {
            if (n is null) yield break;
            yield return n.Value;
            foreach (var x in Walk(n.Left)) yield return x;
            foreach (var x in Walk(n.Right)) yield return x;
        }
        return Walk(Root);
    }
}

//       4
//      / \
//     2   6
//    / \
//   1   3
var tree = new BinaryTree
{
    Root = new Node(4)
    {
        Left = new Node(2) { Left = new Node(1), Right = new Node(3) },
        Right = new Node(6)
    }
};
Console.WriteLine("中序: " + string.Join(",", tree.InOrder()));   // 1,2,3,4,6
Console.WriteLine("先序: " + string.Join(",", tree.PreOrder()));  // 4,2,1,3,6
Console.WriteLine("偶数: " + string.Join(",", tree.InOrder().Where(x => x % 2 == 0)));

