public interface IChatMediator
{
    void Register(User user);
    void Broadcast(User from, string msg);
    void Whisper(User from, string toName, string msg);
}

public class User
{
    public string Name { get; }
    private IChatMediator _room;
    public User(string name) => Name = name;
    internal void Join(IChatMediator room) => _room = room;
    public void Say(string msg) => _room.Broadcast(this, msg);
    public void Whisper(string to, string msg) => _room.Whisper(this, to, msg);
    public void Receive(string from, string msg, bool priv) =>
        Console.WriteLine($"{Name} 收到{(priv ? "私信" : "")} [{from}]: {msg}");
}

public class ChatRoom : IChatMediator
{
    private readonly List<User> _users = new();
    public void Register(User u)
    {
        u.Join(this);
        _users.Add(u);
        Console.WriteLine(u.Name + " 加入房间");
    }
    public void Broadcast(User from, string msg)
    {
        foreach (var u in _users)
            if (u != from) u.Receive(from.Name, msg, false);
    }
    public void Whisper(User from, string toName, string msg)
    {
        var to = _users.Find(u => u.Name == toName);
        to?.Receive(from.Name, msg, true);
    }
}

