using System;
using System.Collections.Generic;

public class Editor
{
    public string Text { get; set; } = "";
    public int Cursor { get; set; }

    public IMemento Save() => new Snapshot(Text, Cursor);

    public void Restore(IMemento m)
    {
        var s = (Snapshot)m;
        Text = s.Text;
        Cursor = s.Cursor;
    }

    public interface IMemento { DateTime TakenAt { get; } }

    // 私有嵌套类：外部拿不到字段，只能当不透明句柄传递
    private class Snapshot : IMemento
    {
        public string Text { get; }
        public int Cursor { get; }
        public DateTime TakenAt { get; } = DateTime.Now;
        public Snapshot(string text, int cursor) { Text = text; Cursor = cursor; }
    }
}

public class History
{
    private readonly Stack<Editor.IMemento> _undo = new();
    private readonly Stack<Editor.IMemento> _redo = new();
    public void Backup(Editor e) { _undo.Push(e.Save()); _redo.Clear(); }
    public void Undo(Editor e)
    {
        if (_undo.Count == 0) return;
        _redo.Push(e.Save());
        e.Restore(_undo.Pop());
    }
    public void Redo(Editor e)
    {
        if (_redo.Count == 0) return;
        _undo.Push(e.Save());
        e.Restore(_redo.Pop());
    }
}

var editor = new Editor();
var hist = new History();
editor.Text = "Hello"; editor.Cursor = 5; hist.Backup(editor);
editor.Text = "Hello World"; editor.Cursor = 11; hist.Backup(editor);
editor.Text = "Hello World!!!";
hist.Undo(editor);
Console.WriteLine(editor.Text);   // Hello World
hist.Undo(editor);
Console.WriteLine(editor.Text);   // Hello
hist.Redo(editor);
Console.WriteLine(editor.Text);   // Hello World

