public sealed record CartItem(string Sku, decimal Price, int Qty);

public interface IPricingStrategy
{
    string Name { get; }
    decimal Quote(IReadOnlyList<CartItem> items);
}

public class NoDiscount : IPricingStrategy
{
    public string Name => "原价";
    public decimal Quote(IReadOnlyList<CartItem> items) => items.Sum(i => i.Price * i.Qty);
}
public class PercentOff : IPricingStrategy
{
    private readonly decimal _off;
    public PercentOff(decimal off) => _off = off;
    public string Name => $"{_off:P0} 折扣";
    public decimal Quote(IReadOnlyList<CartItem> items) =>
        items.Sum(i => i.Price * i.Qty) * (1 - _off);
}
public class BuyTwoGetOne : IPricingStrategy
{
    public string Name => "满三免一";
    public decimal Quote(IReadOnlyList<CartItem> items)
    {
        decimal total = 0;
        foreach (var i in items)
        {
            var free = i.Qty / 3;
            total += i.Price * (i.Qty - free);
        }
        return total;
    }
}

public class Checkout
{
    public IPricingStrategy Strategy { get; set; }
    public Checkout(IPricingStrategy s) => Strategy = s;
    public void Print(IReadOnlyList<CartItem> items)
    {
        var pay = Strategy.Quote(items);
        Console.WriteLine($"{Strategy.Name}: ¥{pay:0.00}");
    }
}

