using System;
using System.Collections.Generic;

public abstract class DataMiner
{
    // 算法骨架：子类不能改流程
    public sealed void Mine(string path)
    {
        var raw = Open(path);
        var rows = Extract(raw);
        if (ShouldTransform()) rows = Transform(rows);
        Analyze(rows);
        HookAfter();
    }

    protected abstract string Open(string path);
    protected abstract List<string> Extract(string raw);
    protected virtual bool ShouldTransform() => true;          // 钩子
    protected virtual List<string> Transform(List<string> rows) => rows;
    protected abstract void Analyze(List<string> rows);
    protected virtual void HookAfter() { }                     // 可选收尾
}

public class CsvMiner : DataMiner
{
    protected override string Open(string path)
    {
        Console.WriteLine("打开 CSV " + path);
        return "name,age\nAda,36\nBob,22";
    }
    protected override List<string> Extract(string raw) =>
        new List<string>(raw.Split('\n'));
    protected override List<string> Transform(List<string> rows)
    {
        rows.RemoveAt(0); // 去掉表头
        return rows;
    }
    protected override void Analyze(List<string> rows) =>
        Console.WriteLine($"CSV 共 {rows.Count} 行");
}

public class JsonMiner : DataMiner
{
    protected override string Open(string path)
    {
        Console.WriteLine("打开 JSON " + path);
        return "[1,2,3]";
    }
    protected override List<string> Extract(string raw) =>
        new List<string> { "1", "2", "3" };
    protected override bool ShouldTransform() => false; // 跳过转换
    protected override void Analyze(List<string> rows) =>
        Console.WriteLine("JSON 元素: " + string.Join(",", rows));
    protected override void HookAfter() => Console.WriteLine("写审计日志");
}

new CsvMiner().Mine("users.csv");
new JsonMiner().Mine("data.json");

