    protected virtual bool CustomerWantsCondiments() => true;
}

public class Tea : CaffeineBeverage
{
    protected override void Brew() => Console.WriteLine("浸泡茶叶");
    protected override void AddCondiments() => Console.WriteLine("加柠檬");
}
public class Coffee : CaffeineBeverage
{
    private readonly bool _sugar;
    public Coffee(bool sugar) => _sugar = sugar;
    protected override void Brew() => Console.WriteLine("冲泡咖啡粉");
    protected override void AddCondiments() => Console.WriteLine("加糖加奶");
    protected override bool CustomerWantsCondiments() => _sugar;
}

new Tea().Prepare();
Console.WriteLine("---");
new Coffee(sugar: false).Prepare();  // 不加调料

