using System;
using System.Collections.Generic;

public interface IShapeVisitor
{
    void Visit(Circle c);
    void Visit(Rectangle r);
    void Visit(Group g);
}

public interface IShape
{
    void Accept(IShapeVisitor v);
}

public class Circle : IShape
{
    public double R { get; }
    public Circle(double r) => R = r;
    public void Accept(IShapeVisitor v) => v.Visit(this);
}
public class Rectangle : IShape
{
    public double W { get; }
    public double H { get; }
    public Rectangle(double w, double h) { W = w; H = h; }
    public void Accept(IShapeVisitor v) => v.Visit(this);
}
public class Group : IShape
{
    public List<IShape> Children { get; } = new();
    public void Accept(IShapeVisitor v) => v.Visit(this);
}

public class AreaVisitor : IShapeVisitor
{
    public double Total { get; private set; }
    public void Visit(Circle c) => Total += Math.PI * c.R * c.R;
    public void Visit(Rectangle r) => Total += r.W * r.H;
    public void Visit(Group g) { foreach (var c in g.Children) c.Accept(this); }
}

public class XmlExportVisitor : IShapeVisitor
{
    public void Visit(Circle c) => Console.WriteLine($"<circle r=\"{c.R}\"/>");
    public void Visit(Rectangle r) => Console.WriteLine($"<rect w=\"{r.W}\" h=\"{r.H}\"/>");
    public void Visit(Group g)
    {
        Console.WriteLine("<g>");
        foreach (var c in g.Children) c.Accept(this);
        Console.WriteLine("</g>");
    }
}

var root = new Group();
root.Children.Add(new Circle(2));
root.Children.Add(new Rectangle(3, 4));
root.Children.Add(new Circle(1));

var area = new AreaVisitor();
root.Accept(area);
Console.WriteLine($"面积 ≈ {area.Total:0.00}");
root.Accept(new XmlExportVisitor());

