using System;
using System.Collections.Generic;
using System.Text;

public interface IDocVisitor
{
    void Visit(Paragraph p);
    void Visit(Heading h);
    void Visit(Doc d);
}
public interface IDocNode { void Accept(IDocVisitor v); }

public class Paragraph : IDocNode
{
    public string Text { get; }
    public Paragraph(string t) => Text = t;
    public void Accept(IDocVisitor v) => v.Visit(this);
}
public class Heading : IDocNode
{
    public int Level { get; }
    public string Text { get; }
    public Heading(int level, string t) { Level = level; Text = t; }
    public void Accept(IDocVisitor v) => v.Visit(this);
}
public class Doc : IDocNode
{
    public List<IDocNode> Children { get; } = new();
    public void Accept(IDocVisitor v) => v.Visit(this);
}

public class WordCountVisitor : IDocVisitor
{
    public int Words { get; private set; }
    public void Visit(Paragraph p) => Words += p.Text.Split(' ', StringSplitOptions.RemoveEmptyEntries).Length;
    public void Visit(Heading h) => Words += h.Text.Split(' ', StringSplitOptions.RemoveEmptyEntries).Length;
    public void Visit(Doc d) { foreach (var c in d.Children) c.Accept(this); }
}
public class MarkdownVisitor : IDocVisitor
{
    private readonly StringBuilder _sb = new();
    public override string ToString() => _sb.ToString();
    public void Visit(Paragraph p) => _sb.AppendLine(p.Text).AppendLine();
    public void Visit(Heading h) => _sb.AppendLine(new string('#', h.Level) + " " + h.Text);
    public void Visit(Doc d) { foreach (var c in d.Children) c.Accept(this); }
}

var doc = new Doc();
doc.Children.Add(new Heading(1, "设计模式"));
doc.Children.Add(new Paragraph("Visitor 把操作从结构中分离"));
doc.Children.Add(new Heading(2, "优点"));
doc.Children.Add(new Paragraph("新增操作不必改元素类"));

var wc = new WordCountVisitor();
doc.Accept(wc);
Console.WriteLine("词数: " + wc.Words);
var md = new MarkdownVisitor();
doc.Accept(md);
Console.WriteLine(md);
